public static enum StaticFileStorageTarget {
    AZURE, GOOGLE
}

public static void uploadObjectToLocalOrAzure(File pdfFile, String documentPath = null) {
    if (GrailsUtil.developmentEnv) {
        log.info("=== Requesting file to be uploaded on Local location ===>>> ${documentPath}")
        File file = new File(documentPath)
        FileUtils.writeByteArrayToFile(file, pdfFile.getBytes())
    } else {
        log.info("=== Requesting file to be uploaded on Azure location ===>>> ${documentPath}")
        uploadObjectToAzure(pdfFile, documentPath)
    }
}

// ********************** GOOGLE CLOUD STORAGE **********************

/**
 * Name of the bucket holding the static documents. It is read from the application configuration and falls back to
 * the environment of the running container so that the value never has to be checked in.
 */
private static String fetchGoogleBucketName() {
    String bucketName = null
    try {
        bucketName = Holders.getFlatConfig()?.get(GOOGLE_BUCKET_CONFIG_KEY)
    }
    catch (Exception e) {
        log.warn("Unable to read '${GOOGLE_BUCKET_CONFIG_KEY}' from the application configuration ==>> ${e.message}")
    }
    if (StringUtils.isBlank(bucketName))
        bucketName = System.getProperty(GOOGLE_BUCKET_CONFIG_KEY) ?: System.getenv("GOOGLE_STORAGE_BUCKET")
    StringUtils.isBlank(bucketName) ? DEFAULT_GOOGLE_BUCKET_NAME : bucketName
}

/**
 * Service account credentials shipped as a classpath resource by the deployed environment. Returns null when the
 * resource(or the auth library able to read it) is not available, which makes the caller use the default credentials
 * of the runtime.
 */
private static Object fetchGoogleServiceAccountCredentials() {
    InputStream credentialStream = HelperMethod.class.getClassLoader().getResourceAsStream(GOOGLE_SERVICE_ACCOUNT_RESOURCE)
    if (!credentialStream)
        return null
    try {
        //Loaded dynamically so that the absence of the auth library only degrades to the default credentials
        return Class.forName("com.google.auth.oauth2.GoogleCredentials").fromStream(credentialStream)
    }
    catch (Throwable t) {
        log.error("Exception while reading Google service account resource ==>> ${t.message}", t)
        return null
    }
    finally {
        credentialStream.close()
    }
}

public static Storage fetchGoogleCloudStorageService() {
    Object credentials = fetchGoogleServiceAccountCredentials()
    credentials ? StorageOptions.newBuilder().setCredentials(credentials).build().getService() :
            StorageOptions.getDefaultInstance().getService()
}

public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (path) {
        final String BUCKET_NAME = fetchGoogleBucketName()
        try {
            Storage storage = fetchGoogleCloudStorageService()
            BlobInfo blobInfo = BlobInfo.newBuilder(BlobId.of(BUCKET_NAME, path)).build()
            storage.create(blobInfo, file.bytes)
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
    InputStream inputStream = null
    if (path) {
        final String BUCKET_NAME = fetchGoogleBucketName()
        try {
            Storage storage = fetchGoogleCloudStorageService()
            BlobId blobId = BlobId.of(BUCKET_NAME, path)
            byte[] content = storage.readAllBytes(blobId)
            if (content == null)
                content = storage.get(blobId)?.getContent()
            if (content != null)
                inputStream = new ByteArrayInputStream(content)
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

public static void uploadObjectToLocalOrGoogleCloudStorage(File pdfFile, String documentPath = null) {
    if (GrailsUtil.developmentEnv) {
        log.info("=== Requesting file to be uploaded on Local location ===>>> ${documentPath}")
        File file = new File(documentPath)
        FileUtils.writeByteArrayToFile(file, pdfFile.getBytes())
    } else {
        log.info("=== Requesting file to be uploaded on Google Cloud Storage location ===>>> ${documentPath}")
        uploadObjectToGoogleCloudStorage(pdfFile, documentPath)
    }
}

