import com.bankScraper.HelperMethod
import com.google.cloud.storage.StorageOptions
import com.google.cloud.storage.contrib.nio.testing.LocalStorageHelper

def fakeOptions = LocalStorageHelper.getOptions()
StorageOptions.metaClass.static.getDefaultInstance = { -> fakeOptions }

// --- upload preserves path and bytes ---
File tmp = File.createTempFile("doc", ".pdf")
byte[] payload = "hello google cloud".bytes
tmp.bytes = payload
String path = "Success_Files/Client_1/08-Aug-2026/ICICI/application-pdf/abc123_statement.pdf"

assert HelperMethod.uploadObjectToGoogleCloudStorage(tmp, path) == Boolean.TRUE

def storage = fakeOptions.service
def blob = storage.get(com.google.cloud.storage.BlobId.of(HelperMethod.DEFAULT_GOOGLE_BUCKET_NAME, path))
assert blob != null: "blob not stored under requested path"
assert blob.getContent() == payload
assert blob.name == path

// --- download returns stored bytes as ByteArrayInputStream ---
InputStream inputStream = HelperMethod.downloadObjectFromGoogleCloudStorage(path)
assert inputStream instanceof ByteArrayInputStream
assert inputStream.bytes == payload

// --- blank path is a no-op ---
assert HelperMethod.uploadObjectToGoogleCloudStorage(tmp, "") == Boolean.FALSE
assert HelperMethod.uploadObjectToGoogleCloudStorage(tmp, null) == Boolean.FALSE
assert HelperMethod.downloadObjectFromGoogleCloudStorage("") == null
assert HelperMethod.downloadObjectFromGoogleCloudStorage(null) == null

// --- storage service obtained through StorageOptions with ambient credentials ---
assert HelperMethod.fetchGoogleCloudStorageService() != null

// --- local upload in development env still writes locally ---
File dir = File.createTempDir()
String localPath = "${dir.absolutePath}/nested/local.pdf"
HelperMethod.uploadObjectToLocalOrGoogleCloudStorage(tmp, localPath)
if (grails.util.GrailsUtil.developmentEnv) {
    assert new File(localPath).bytes == payload
} else {
    def stored = storage.get(com.google.cloud.storage.BlobId.of(HelperMethod.DEFAULT_GOOGLE_BUCKET_NAME, localPath))
    assert stored != null && stored.getContent() == payload
}

tmp.delete()
println "ALL GOOGLE STORAGE CHECKS PASSED (env=${grails.util.Environment.current})"

